import type { TPendencia, TPendenciaListagem } from '../types/pendencia';
import { extractPendenciasFromDue } from './mapPendenciaApiToScreen';
import { isPendenciaAberta } from './pendenciaStatus';

type TPendenciasEmbeddedSource = {
    pendencias?: TPendenciaListagem | null;
};

export function getPendenciasData(item: TPendenciasEmbeddedSource): TPendencia[] {
    return extractPendenciasFromDue(item);
}

export function countOpenPendencias(item: TPendenciasEmbeddedSource): number {
    return getPendenciasData(item).filter((pendencia) => isPendenciaAberta(pendencia))
        .length;
}

export function hasOpenImpeditivaPendencia(item: TPendenciasEmbeddedSource): boolean {
    return getPendenciasData(item).some(
        (pendencia) => isPendenciaAberta(pendencia) && Boolean(pendencia.impedimento),
    );
}

